firestore.rules:
service cloud.firestore {
  match /databases/{database}/documents {

    // Helper functions
    function isSignedIn() {
      return request.auth != null;
    }

    function isOwner(userId) {
      return request.auth.uid == userId;
    }

    function isAdmin() {
      return isSignedIn() && exists(/databases/$(database)/documents/admins/$(request.auth.uid));
    }

    function isVerified() {
      return isSignedIn() && request.auth.token.email_verified == true;
    }

    // Users Collection
    // Users can read their own data, admins can read all
    match /users/{userId} {
      allow read: if isOwner(userId) || isAdmin();
      allow create: if isSignedIn() && isOwner(userId);
      allow update: if isOwner(userId) || isAdmin();
      allow delete: if isAdmin();
    }

    // Profiles Collection
    // Users can manage their own profiles
    match /profiles/{userId} {
      allow read: if isOwner(userId) || isAdmin();
      allow create: if isSignedIn() && isOwner(userId);
      allow update: if isOwner(userId) || isAdmin();
      allow delete: if isAdmin();
    }

    // Orders Collection
    // Users can read their own orders, create new orders
    match /orders/{orderId} {
      allow read: if isSignedIn() && 
                     (resource.data.user_id == request.auth.uid || isAdmin());
      allow create: if isSignedIn() && 
                       request.resource.data.user_id == request.auth.uid;
      allow update: if isAdmin() || 
                       (isOwner(resource.data.user_id) && 
                        request.resource.data.status == 'cancelled');
      allow delete: if isAdmin();
    }

    // Reviews Collection
    // Anyone can read approved reviews, users can create their own
    match /reviews/{reviewId} {
      allow read: if resource.data.is_approved == true || 
                     isOwner(resource.data.user_id) || 
                     isAdmin();
      allow create: if isSignedIn() && 
                       request.resource.data.user_id == request.auth.uid && 
                       request.resource.data.is_verified_purchase == true;
      allow update: if isOwner(resource.data.user_id) || isAdmin();
      allow delete: if isOwner(resource.data.user_id) || isAdmin();
    }

    // Contact Submissions
    // Users can create contact submissions, only admins can read/update
    match /contact_submissions/{submissionId} {
      allow read: if isAdmin();
      allow create: if true; // Anyone can submit
      allow update: if isAdmin();
      allow delete: if isAdmin();
    }

    // Newsletter Subscribers
    // Anyone can subscribe, only admins can manage
    match /newsletter_subscribers/{subscriberId} {
      allow read: if isAdmin();
      allow create: if true; // Anyone can subscribe
      allow update: if isAdmin();
      allow delete: if isAdmin();
    }

    // Notifications
    // Users can read their own notifications
    match /notifications/{notificationId} {
      allow read: if isOwner(resource.data.user_id) || isAdmin();
      allow create: if isAdmin();
      allow update: if isOwner(resource.data.user_id) || isAdmin();
      allow delete: if isOwner(resource.data.user_id) || isAdmin();
    }

    // Blog Posts
    // Anyone can read published posts, only admins can manage
    match /blog_posts/{postId} {
      allow read: if resource.data.is_published == true || isAdmin();
      allow create: if isAdmin();
      allow update: if isAdmin();
      allow delete: if isAdmin();
    }

    // Admins Collection
    // Only existing admins can read and manage
    match /admins/{adminId} {
      allow read: if isAdmin();
      allow create: if isAdmin();
      allow update: if isAdmin();
      allow delete: if isAdmin();
    }

    // Deny all other access
    match /{document=**} {
      allow read, write: if false;
    }
  }
}

realtimeDatabase.rules:
{
  "rules": {
    ".read": false,
    ".write": false,

    "products": {
      ".read": true,
      ".write": "auth != null && root.child('admins').child(auth.uid).exists()",
      ".indexOn": ["category", "price", "stock_status", "is_featured"]
    },

    "categories": {
      ".read": true,
      ".write": "auth != null && root.child('admins').child(auth.uid).exists()",
      ".indexOn": ["name", "is_active"]
    },

    "carts": {
      "$uid": {
        ".read": "auth != null && auth.uid === $uid",
        ".write": "auth != null && auth.uid === $uid",
        ".validate": "newData.hasChildren(['user_id', 'items', 'updated_at'])",
        "user_id": {
          ".validate": "newData.val() === $uid"
        },
        "items": {
          "$product_id": {
            ".validate": "newData.hasChildren(['product_id', 'name', 'price', 'quantity'])"
          }
        },
        "updated_at": {
          ".validate": "newData.isString()"
        },
        "created_at": {
          ".validate": "newData.isString()"
        }
      }
    },

    "wishlists": {
      "$uid": {
        ".read": "auth != null && auth.uid === $uid",
        ".write": "auth != null && auth.uid === $uid",
        ".validate": "newData.hasChildren(['user_id', 'items'])",
        "user_id": {
          ".validate": "newData.val() === $uid"
        },
        "items": {
          "$product_id": {
            ".validate": "newData.hasChildren(['product_id', 'added_at'])"
          }
        },
        "updated_at": {
          ".validate": "newData.isString()"
        }
      }
    },

    "admins": {
      ".read": "auth != null && root.child('admins').child(auth.uid).exists()",
      ".write": "auth != null && root.child('admins').child(auth.uid).exists()"
    }
  }
}
